) AS (
  VALUES 
    (296::BIGINT, 'Es la profesora menos humana del TEC SJ, a decir verdad, sus clases son agobiantes y espera perfección, no acepta menos.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Clases largas']::TEXT[], '2026-09-28T00:00:00+00:00'::TIMESTAMPTZ, '93f65edb8e9e37b0db57db5facae2f4d237e025c50a4fd5aa84b9587e2043e2b'::TEXT, ARRAY[1052]::BIGINT[]),
    (296::BIGINT, 'Realmente la mayoria de comentarios negativos es porque la gente quiere pasar sin hacer absolutamente nada. Pasé el curso con 100 jugando en clases, era virtual. El examén realmente es sencillo y los quices tambien. Lo unico dolor es la asistencia y que son presentaciones larguisimas.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Tomaría su clase nuevamente']::TEXT[], '2026-08-06T00:00:00+00:00'::TIMESTAMPTZ, '581c41da65a2998b6eb20ed1772bf1b41ac1122962668fdb386f79138605f73c'::TEXT, ARRAY[1158]::BIGINT[]),
    (296::BIGINT, 'Impresionante! Cumple el cronograma que da desde el día uno, se nota sabe mucho de los temas porque ya ha trabajado en ello. Es realista con el mundo laboral y conforme a eso enseña, muy dinámica e interesante cada clase. Mejor clases presenciales porque sino nota muchos no están en clase realmente'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Clases excelentes']::TEXT[], '2026-08-03T00:00:00+00:00'::TIMESTAMPTZ, 'c1d8f207038e4ad4a7c6e087cb02ae35c772a770e27c89a8e0bfad4001a7a90c'::TEXT, ARRAY[1052, 1037]::BIGINT[]),
    (296::BIGINT, 'Las clases son un poco más dinamicas comparadas a otros cursos que da y la materia que enseña si llega a ser bastante útil e interesante. No califica muy duro pero el proyecto es con todos los del curso así que si hay que tener mucho orden para realizarlo'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria']::TEXT[], '2026-07-10T00:00:00+00:00'::TIMESTAMPTZ, '9157eae34fea4c56524f7b73462862c0911fff96045db847034624a748ff87f8'::TEXT, ARRAY[1052]::BIGINT[]),
    (296::BIGINT, 'Este curso lo tomé en primer semestre y bueno, no me gusta mucho la programación, sin embargo la profe lo volvió interesante haciendo que uno participe e invente cosas, programamos en Python, la profe solía leer las diapositivas y rayarlas para subirlas rayadas, había que ver los videos de nuevo.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2025-12-06T00:00:00+00:00'::TIMESTAMPTZ, '99c7667b9210312aac5320f2a1e24a08a76eb05ddcc4b6b95670dfea7380d5b6'::TEXT, ARRAY[1249]::BIGINT[]),
    (296::BIGINT, 'Nunca había visto a un androide, hasta que conocí a esta profesora. Piensa que uno es igual de robótico e inhumano que ella, desde semana 1 te presiona para que tengas terminado el proyecto en semana 3, mas, sin embargo, no explica más allá de como usar sql y de como diagramar. No matricule, huya..'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Deja trabajos largos']::TEXT[], '2025-04-26T00:00:00+00:00'::TIMESTAMPTZ, '8ac2f3e52eaa016d01c68f24e0441bf6465a79441099d430bd3a703da8e52244'::TEXT, ARRAY[1037]::BIGINT[]),
    (296::BIGINT, 'Demasiados labs y entregables La profe es ruda y no tiene humanidad dentro de su corazon'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-02-10T00:00:00+00:00'::TIMESTAMPTZ, 'a454870543437a7573273bf09c550c23d5657ecd734d3db8424bdced58a7a762'::TEXT, ARRAY[1151]::BIGINT[]),
    (296::BIGINT, 'La mejor profe para Ap, deja bastante trabajo, pero sencillo de realizar. Se nota que la profe sabe de lo qué está hablando.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos', 'Tomaría su clase nuevamente']::TEXT[], '2024-11-18T00:00:00+00:00'::TIMESTAMPTZ, 'bfabc1fa5cff21ca0b53fe0a03a50e35ae275dfdab2ef9139145771e478efbc6'::TEXT, ARRAY[1052]::BIGINT[]),
    (296::BIGINT, 'Al ser la primera vez que da el curso, estaba un poco "perdida". Sin embargo, siempre ayuda, y la evaluación del curso estaba para pasar.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo']::TEXT[], '2024-06-05T00:00:00+00:00'::TIMESTAMPTZ, '5c3575af845f75f342cedc512d52fa03ecbfd1d8914ebf94b94d53dc181baf6d'::TEXT, ARRAY[1151]::BIGINT[]),
    (296::BIGINT, 'Es la primera vez en dar este curso, prácticamente todo el semestre fue simplex. Se preocupaba que todos entendiera la materia. y da las notas muy puntual, estoy en semana 16 ya evaluó el 85% de la nota. La clave para pasar, tener un buen equipo de trabajo, y el resto se hace solo'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Muchos proyectos grupales']::TEXT[], '2024-05-26T00:00:00+00:00'::TIMESTAMPTZ, 'aad4146ea7a45b0f4de3646a52dec8a29c87daaab3caf3f9620c37cc35171d1d'::TEXT, ARRAY[1151]::BIGINT[]),
    (296::BIGINT, 'Buena profe, puede parecer bastante seria al principio pero en realidad da la clase de una manera muy amigable y si es estudiante si va a ser buena nota con usted. Si deja varios laboratorios, pero con las diapositivas que tiene se soluciona la mayoría. Los proyectos si son de hacerlos con tiempo'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Asistencia obligatoria']::TEXT[], '2024-01-31T00:00:00+00:00'::TIMESTAMPTZ, '41fad7f3166474f5d5aa49584a4b4d1a762b6c1ccb10bbea800bd4541a410607'::TEXT, ARRAY[1037]::BIGINT[]),
    (296::BIGINT, 'Pésima profesora, la materia de las diapositivas son sacadas de páginas de dudosa credibilidad. No se aprende nada de IA, solo conceptos para bebés, con solo decirles que explica algoritmos con Excel. Por eso mismo el curso se pasa con 100, los labs/quices son regalados.'::TEXT, 10.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Clases largas']::TEXT[], '2024-01-17T00:00:00+00:00'::TIMESTAMPTZ, '567d436b39f01730bdc95e8dc2dfc06a0443aad6acbdda119de881ec0026c920'::TEXT, ARRAY[1162]::BIGINT[]),
    (296::BIGINT, 'Es un curso muy dinámico. Las evaluaciones están muy bien distribuidas para pasar. La profe atiende muy rápido las dudas y se preocupa por que el estudiante aprenda.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2023-12-18T00:00:00+00:00'::TIMESTAMPTZ, 'de235d591fc6aa40aa825ab5564f7272da1649f347db69ea84ac3611eaa58c1b'::TEXT, ARRAY[1052]::BIGINT[]),
    (296::BIGINT, 'Casi cada clase se realiza un laboratorio, las exposiciones de la profe no ayudan mucho pero se logra entender lo básico. Solo hay un proyecto grande y sin exámenes . Me pareció un curso pesado pero con un buen grupo se puede pasar( todas las actividades son en grupo).'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-12-05T00:00:00+00:00'::TIMESTAMPTZ, 'df9d2db00d0e214d6ebd905c80832beeb2f18524413e44be0d2c9ca81612d2bc'::TEXT, ARRAY[1037]::BIGINT[]),
    (296::BIGINT, 'La profe es muy buena, sabe de lo que habla y su experiencia la respalda. Solamente, que confía en que las cosas que solucionan hablando entre estudiantes y no siempre es así, las evaluaciones deja poco tiempo pero se puede negociar. Aprenda a usar Project y Excel. :D'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Clases excelentes']::TEXT[], '2023-12-04T00:00:00+00:00'::TIMESTAMPTZ, '73a9123bd717d56956b0c952b678d8455e864c97867a4fb9f6de162028d6ddc8'::TEXT, ARRAY[1052]::BIGINT[]),
    (296::BIGINT, 'Uno aprende. Los proyectos son masivos, a la gente le va muy muy mal. La distribución del curso es buena, ayuda a pasar. Sin un buen grupo es muy difícil pasar'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Respetado por los estudiantes', 'Deja trabajos largos']::TEXT[], '2023-11-27T00:00:00+00:00'::TIMESTAMPTZ, 'e47278eeffd788ca7922e0cc9b76859f0435855d16c27e77e8f0a54fba994f7d'::TEXT, ARRAY[1037]::BIGINT[]),
    (296::BIGINT, 'Es muy buena profe, los labs son algo sencillos si se pone atención en clase. La mayoría de tareas es en parejas, asegurese de tener un buen grupo de trabajo para realizar el proyecto/lab. Pero en sí, la distribución de la nota del curso hace que uno pueda pasar perfectamente, solo es de ponerle.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Brinda apoyo', 'Deja trabajos largos']::TEXT[], '2023-06-30T00:00:00+00:00'::TIMESTAMPTZ, '34ecc14834234758b924a9be35029fb12073c91372ea66859608aaf20544689b'::TEXT, ARRAY[1037]::BIGINT[]),
    (296::BIGINT, 'El curso consistió en realizar laboratorios, quizzes, tareas y una investigación sobre un tema que ella te pone a elegir. Todo lo anterior es sencillo si se pone atención en clases, de lo contrario hay que buscar en internet. Sí la clase es virtual, no la graba. Aprendí bastante.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-24T00:00:00+00:00'::TIMESTAMPTZ, '8c92a4af1442515d1c06a8c6aec212a51c03cc34f4ec130e984844798b794f70'::TEXT, ARRAY[1162]::BIGINT[]),
    (296::BIGINT, 'Ella en presencial es la mejor! Las clases son relajadas , divertidas y se aprende un monton . Tenia mucho miedo por los comentarios anteriores , pero si valio total la pena . Solo busquen un buen grupo de trabajo . Literal perdí puntos solo por mis compañeros de trabajo .'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación']::TEXT[], '2023-06-22T00:00:00+00:00'::TIMESTAMPTZ, 'a6e1f4388b2a018145fb84c424e2736016952154be1e47d7aa000a8848297aa9'::TEXT, ARRAY[1037]::BIGINT[]),
    (296::BIGINT, '(Verano) La profe explica muy bien la materia y es buena gente, la distribución de la evaluación favorece bastante. Se realizan trabajos en clase tipo laboratorios/foros los cuales se hacen en grupo. Tenga buen grupo ya que el proyecto es pesado.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2023-01-30T00:00:00+00:00'::TIMESTAMPTZ, 'bb5eee172e5c325cc3e774e948dd333f34ab3165ab5839d123d01cf9a5aad8b8'::TEXT, ARRAY[1037]::BIGINT[]),
    (296::BIGINT, 'Excelente profesora para llevar el curso, la materia es densa pero ella ayuda mucho a entender. En comparación a los semestres anteriores mejoró mucho. Ella deja muchos laboratorios en parejas entonces trate de no faltar a ninguna clase'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Clases largas']::TEXT[], '2022-12-02T00:00:00+00:00'::TIMESTAMPTZ, '3e652ac5b8b231c7d5291f5552b237a40e77d9bbc966dc1bcbf150b0afc497e6'::TEXT, ARRAY[1162]::BIGINT[]),
    (296::BIGINT, 'La profesora es bastante buena y conoce de lo que habla, los quices pueden ser rudos, los laboratorios y proyectos son siempre en parejas o grupos, eso no quita que lleven su tiempo. No deje nada para último momento, no falte nunca y vaya sí o sí a consulta, preguntar, preguntar y preguntar.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Da crédito extra', 'Muchos proyectos grupales']::TEXT[], '2022-11-13T00:00:00+00:00'::TIMESTAMPTZ, 'c7eceb5411ae92dbd495a76a7abff5afbeb27651f528eb1391ddf7741c46aa82'::TEXT, ARRAY[1037]::BIGINT[]),
    (296::BIGINT, 'No es dificil pero no es para nada facil, busque un buen grupo, no deje los proyectos para la ultima semana. Pasar con ella no es imposible pero si tiene que tener buen grupo y organizar bien tiempos. En comparacion a semestres anteriores mejoro mucho.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'La participación importa', 'Muchos proyectos grupales']::TEXT[], '2022-06-28T00:00:00+00:00'::TIMESTAMPTZ, 'f65958401f262c75fe60b67c8dece1b231b254a2578bc5fb3859afc7fb8ba2c8'::TEXT, ARRAY[1037]::BIGINT[]),
    (296::BIGINT, 'Pocos docentes son tan malos como ella, muchas veces para ser simplemente despiadada para calificar. Ni ella misma parece tener claro los proyectos que envía. Conoce bien su materia pero lo más dificil de su materia es cumplir con los requisitos sacados de la manga que ella da'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Deja trabajos largos']::TEXT[], '2022-06-13T00:00:00+00:00'::TIMESTAMPTZ, 'ce92c045f25bbde8b71dbead04ce28e1d451c0a4bbbdfece22665d66234cc2b2'::TEXT, ARRAY[1037]::BIGINT[]),
    (296::BIGINT, '(Verano) La profe explica y trata que sea entretenido y llamativo entonces lo hace con ejemplos de superheroes y sus poderes en vez de relaciones algebraicas, al principio cuesta entender pero ya luego es fácil. Un proyecto muy grande, busque buen grupo'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2022-02-03T00:00:00+00:00'::TIMESTAMPTZ, 'fbbf47398c425310a7a4ac86c7e802a050d8d2966a11ae86e34d6a2cb5a0884f'::TEXT, ARRAY[1037]::BIGINT[]),
    (296::BIGINT, 'Que infierno esta señora, de esos profes que no enseñan nada pero piden de todo, a veces no entiendo cómo esta universidad raja de ser buena pero tiene profesores del asco cómo esta mae...'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas']::TEXT[], '2021-09-09T00:00:00+00:00'::TIMESTAMPTZ, '6329993db455baf872b335ff8af7167ad61131b93a08e115d1a4bd656b0fe9e7'::TEXT, ARRAY[1052]::BIGINT[]),
    (296::BIGINT, 'La profeosra no tiene conocimiento del tema de IA, realmente no se aprende nada porque NO explica. No sabe lo que quiere, es irracional con las tareas y no responde preguntas.EVITENLA si se quieren ahorrar dolores de cabeza, sobra decir que no tomaria sus clases otra vez mejor matricule en otra sede'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Deja trabajos largos']::TEXT[], '2021-08-25T00:00:00+00:00'::TIMESTAMPTZ, 'b37141db366ba7dbd2f04222ea1f0264942c5ae38f7331321026e2f4c4a9da0f'::TEXT, ARRAY[1162]::BIGINT[]),
    (296::BIGINT, 'Es bastante difícil con las clases asincrónicas, llevé ambos, sincrónico y asincrónico y definitivamente es mejor que sean sincrónicos porque sus cursos no se prestan para solo dejar lecturas. La profe es buena pero su metodología virtual-asincrónica no lo es.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Exámenes retadores']::TEXT[], '2021-07-22T00:00:00+00:00'::TIMESTAMPTZ, '40508587dd0ec8e9d1f0f322b8943cd3e6dd6343b2f34bc12eaa34626aaa0bb4'::TEXT, ARRAY[1037]::BIGINT[]),
    (296::BIGINT, 'No es clara con lo que pide, cambia las instrucciones de los trabajos sobre la marcha. Puede llegar a ser poco comprensiva. Sabe mucho y es buena enseñando, pero todo lo demás es más difícil de lo que podría ser Puede ser que las clases virtuales sean las que agraven esta situación con ella.'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Deja trabajos largos']::TEXT[], '2021-07-21T00:00:00+00:00'::TIMESTAMPTZ, 'ff1db02bb9d161f13d7b19a5875129530699c2387250b35e17406329954ed927'::TEXT, ARRAY[1037]::BIGINT[]),
    (296::BIGINT, 'Uno no aprende nada con ella lamentablemente el curso que matricule realmente fue un calvario no explico nada todo era lecturas y presentaciones incompletas , en los examenes se sacaba cosas que no estaban explicadas correctamente en las diapositivas y segun ella uno tenia que hacerle consultas,'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Requiere mucha lectura']::TEXT[], '2021-07-14T00:00:00+00:00'::TIMESTAMPTZ, '5954481402f82a1161f0c2d25e62e3bc0533d568f7e4fad759f5bf8a14b1480b'::TEXT, ARRAY[1052]::BIGINT[]),
    (296::BIGINT, 'No sabe enseñar y ni quiere enseñar. Injusta, puros berrinches por todo.. Un asco de persona y no se aprende nada'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria']::TEXT[], '2021-07-14T00:00:00+00:00'::TIMESTAMPTZ, '03ae553d128fd71b9592aff27358001b4c64175ef378721ea35de71f8a61ec24'::TEXT, ARRAY[1052]::BIGINT[]),
    (296::BIGINT, 'Irracional para calificar exámenes, por una cosa que hagás mal te pone todo malo. El primer examen nada que ver con la materia que dejó y parecía que lo hizo la noche antes en carreras. No enseña nada, todo el curso es asincrónico, deja el proyecto y con el tiempo lo cambia y le agrega más y más.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Deja trabajos largos']::TEXT[], '2021-06-23T00:00:00+00:00'::TIMESTAMPTZ, '1c1dd4fe4fc832e1c6fc0ef3bf10dfea59250c4a72a9fe6624e99e550f115fb7'::TEXT, ARRAY[1037]::BIGINT[]),
    (296::BIGINT, 'No sabe dar clases. Es injusta y no tiene dominio de nada. LA PEOR CLASE VIRTUAL'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-06-14T00:00:00+00:00'::TIMESTAMPTZ, '04080e557152c92a078f1c63472586c953e7691cb36a041e423a95c6da9aa981'::TEXT, ARRAY[1052]::BIGINT[]),
    (296::BIGINT, 'Muy mala profesora, se nota que NO tiene dominios en el área de IA y que llevó un curso por encima. En virtualidad hace el curso 100% asincrónico, presentaciones NADA claras y con información robada de internet, de igual forma los trabajos son ambiguos y están muy mal redactados. ÉVITENLA.'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2021-06-12T00:00:00+00:00'::TIMESTAMPTZ, '688da85754c7d8ca2f4eefb2de9a691d1fae08d99107c9459232f22b6cbe8dbd'::TEXT, ARRAY[1162]::BIGINT[]),
    (296::BIGINT, '(Virtual, asincrónica) Es demasiado irracional al calificar evaluaciones, quiere que todo esté como ella quiere, a pesar de que no lo indicó en las instrucciones. Las tareas son confusas, siempre hay algo ambiguo.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Requiere mucha lectura']::TEXT[], '2021-06-01T00:00:00+00:00'::TIMESTAMPTZ, 'f250378b76767d935fd95792c298b64785671d977996f676bd8a13511e6ca121'::TEXT, ARRAY[1037]::BIGINT[]),
    (296::BIGINT, '(Virtual) Los proyectos son muy grandes, pero si los hace con tiempo de fijo los logra. Deja muchos labs, pero son muy útiles para entender la materia, es un poco estricta y le gusta que participen en clases, pero en general pienso que es muy buena con el curso y prepárense para conocer a sus perros'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Deja trabajos largos']::TEXT[], '2021-02-12T00:00:00+00:00'::TIMESTAMPTZ, '94bf16d4713adf2669eff2151f887324e27207042c339ac82fef905b2bcf11b1'::TEXT, ARRAY[1037]::BIGINT[]),
    (296::BIGINT, 'Si pudiera poner al estudiante a dar la clase lo haría, es una vaga que solo deja trabajos largos y tediosos. Para variar, si uno le pide ayuda es cómo sacar cita en un Ebais. Evitela'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Asistencia obligatoria']::TEXT[], '2021-01-10T00:00:00+00:00'::TIMESTAMPTZ, '72a5e6c2fc1e073f24eaa4ac25e1c221f31e681d10903d049bc7fc2fca20ba6d'::TEXT, ARRAY[1037]::BIGINT[]),
    (296::BIGINT, 'Ella solo se pone a preguntar en las clases esperando que los alumnos contesten sin siquiera haber dado la materia y satura al estudiante con laboratorios junto a los proyectos.'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'La participación importa']::TEXT[], '2021-01-10T00:00:00+00:00'::TIMESTAMPTZ, '2c52cf99fadf88abab0214e5531f9da4e24d79f883e483dabbf2c866ac53aa2e'::TEXT, ARRAY[1037]::BIGINT[]),
    (296::BIGINT, 'Excelente profesora, siempre dispuesta a ayudar al estudiante, deja proyectos un tanto largos pero nada que no se pueda realizar. Sus clases son un poco aburridas pero al final se aprende mucho la verdad.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Inspirador', 'Aspectos de calificación claros']::TEXT[], '2020-12-17T00:00:00+00:00'::TIMESTAMPTZ, '31ab78d42813beffee05455aa0dc916454fb6e60b864dcf9a1e9ed794adda684'::TEXT, ARRAY[1037]::BIGINT[]),
    (296::BIGINT, 'El curso tiene mucha materia pero la profesora sabe cómo hacer que el conocimiento fluya, solo es de ir al día. Los laboratorios sirven para entender mejor la materia y a la hora del proyecto uno ya está mucho más preparado. Es un amor de profesora'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Pocos exámenes', 'Brinda apoyo']::TEXT[], '2020-12-01T00:00:00+00:00'::TIMESTAMPTZ, '2ff7ee2174f6fdee6530b8b42ee878053ee7df1cd76b173f8b0032d646b6948e'::TEXT, ARRAY[1037]::BIGINT[]),
    (296::BIGINT, 'La profe es buena gente y los trabajos son llevaderos, eso sí, ud tiene que empezar los proyectos con tiempo, si deja todo para última hora no le va a dar tiempo, pero en general a lo largo del curso ud va aprendiendo y desarrollando el proyecto y así todo se vuelve muy sencillo'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Respetado por los estudiantes']::TEXT[], '2020-11-26T00:00:00+00:00'::TIMESTAMPTZ, '8d324bd0a0e393a6a12a128c8f6f7e5181e04cfc145b74baf0570ff80c1e3c8d'::TEXT, ARRAY[1037]::BIGINT[]),
    (296::BIGINT, 'Es absurdamente irracional y más en clases virtuales, como ella no revisa los trabajos ni las tareas sólo se encarga de asignar y ya, la cantidad de tiempo entre evaluación y evaluación es muy poca y satura tanto con laboratorios y tareas que al final no queda ni tiempo para trabajar en proyectos'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Deja trabajos largos']::TEXT[], '2020-10-29T00:00:00+00:00'::TIMESTAMPTZ, '66886cc1b6713dd5c2ae5e9027bd72af79201c44cfdfa54b92c23da73988fa2d'::TEXT, ARRAY[1037]::BIGINT[]),
    (296::BIGINT, 'Hay muchas cosas que mejorar en el curso de Administración de Proyectos. Los examenes eran un poco ambigüos. Sí usted le pone pasa muy bien el curso. Ella es su cliente, así que le debe sacar TODOS los requerimientos con lujo y detalle.'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-26T00:00:00+00:00'::TIMESTAMPTZ, '9096a261970aad2be5033b30263e2340e49424c7191002542909a2a9ff629589'::TEXT, ARRAY[1052]::BIGINT[]),
    (296::BIGINT, 'En clases virtuales se niega a grabar y si lo hace tampoco te confíes porque no deja las clases a mano, si se las pides porque no pudiste estar en clase, te mandará a hablar con el coordinador de la carrera. Con respecto a los trabajos son larguísimos y suele dejar un tiempo muy corto para eso.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2020-08-20T00:00:00+00:00'::TIMESTAMPTZ, '502365eb153607ae45274b768f53379d21a9cfe4d3972919961442d0a2f7f464'::TEXT, ARRAY[1037]::BIGINT[]),
    (296::BIGINT, 'Ella no quiere grabar las clases en esta modalidad virtual, si uno le pregunta algo ella responde con "Yo no le voy a enseñar a hacer proyectos", no lleve con ella en modalidad virtual, no le interesa el estudiante.'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Requiere mucha lectura']::TEXT[], '2020-08-20T00:00:00+00:00'::TIMESTAMPTZ, 'fc9c8e147bb75bdd3acbc7b2d417d8200ef2a21ecfbf8c1e68a11e5b163a4dbf'::TEXT, ARRAY[1037]::BIGINT[]),
    (296::BIGINT, 'No lleven AP con Adriana, matriculen en otra sede si es necesario'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas']::TEXT[], '2020-08-16T00:00:00+00:00'::TIMESTAMPTZ, '95546bbd0845cfb00bb967af64fbd5de5621c574ebbf0a3e1ae616fc749afe37'::TEXT, ARRAY[1052]::BIGINT[]),
    (296::BIGINT, 'Se centra en aspectos ajenos al curso, demanda más tiempo que cualquier otro curso. Muy grosera y poco considerada con los estudiantes. Las evaluaciones son sumamente larga y casi no deja rúbricas o especificaciones'::TEXT, 8.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria']::TEXT[], '2020-08-16T00:00:00+00:00'::TIMESTAMPTZ, '164a53134b2f8c8959941b1f34d7d865aa8394bc96928404c4e0a9f7bc0a05d6'::TEXT, ARRAY[1052]::BIGINT[]),
    (296::BIGINT, 'No entiendo para que es necesario ir a clases si no se aprende nada, sin embargo, es obligatorio. Se centra demasiado en cosas ajenas al curso cómo la programación web, digo, el curso era de bases de datos, no programación web. A menos que ud sea el tipo de estudiante "lame botas" no vaya con ella.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Asistencia obligatoria']::TEXT[], '2020-06-22T00:00:00+00:00'::TIMESTAMPTZ, '4dcce1a2b49fb5ae76faeec756b64478e84d3181c937f46d887cd2c2e5e59e8f'::TEXT, ARRAY[1037]::BIGINT[]),
    (296::BIGINT, 'Es muy buena en los cursos de Bases de Datos, en otros cursos como POO no tanto. Es muy extricta con las entregas de proyectos, ninguna tarea ni proyecto tarde (tarde = 0). No califica duro, pero el nivel de los exámenes es superior a lo visto en clase.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores', 'Asistencia obligatoria']::TEXT[], '2019-08-12T00:00:00+00:00'::TIMESTAMPTZ, '4d5318525bbfc3eb8889465ddc465e5bb248ed56d9e6795e9e4f2201c36117b8'::TEXT, ARRAY[1037]::BIGINT[]),
    (296::BIGINT, 'Adriana es muy buena profe! Explica bastante bien. Los exámenes son a otro nivel de la materia vista en clases. Estricta con los proyectos. Da puntos extra en diversas actividades.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Exámenes retadores']::TEXT[], '2019-07-26T00:00:00+00:00'::TIMESTAMPTZ, 'e1308056d3b28f694dbaf2caa36bdb142d5f70a5c1620bb5ec91adca0c91d07f'::TEXT, ARRAY[1037]::BIGINT[]),
    (296::BIGINT, 'El curso debería de ser liviano, pero con esta profesora se vuelve bastante pesado, ella piensa que está en 15 créditos o algo por el estilo. Hay proyecto programado inclusive, si puede evitarla sería una excelente opción.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Asistencia obligatoria']::TEXT[], '2019-06-20T00:00:00+00:00'::TIMESTAMPTZ, '0ad8ab70b03aa578ef8d0518a77b7ee88d68ff96359239a7822ff03ebfef7642'::TEXT, ARRAY[1156]::BIGINT[]),
    (296::BIGINT, 'Es muy buena pero si no le ponen se van a quedar. Si lee esto profe: gracias por existir :) love u.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Clases excelentes']::TEXT[], '2019-03-09T00:00:00+00:00'::TIMESTAMPTZ, 'ae01b74ac322aa22f1930668d3763c73d82a2cb5d5dc6855f5fccf1de9e9fa14'::TEXT, ARRAY[1037]::BIGINT[]),
    (296::BIGINT, 'Es la profesora que menos se entiende, cuando llevé el curso nos confundió muchísimo con el proyecto. Los exámenes son totalmente a percepción de ella, si puede evitarla hágalo. Tiene una estúpidez que es un cuadrito de llegadas tardías que no sé ni qué propósito tiene.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Asistencia obligatoria']::TEXT[], '2018-12-08T00:00:00+00:00'::TIMESTAMPTZ, '6d60727546229985e05995511bfd30bf39f923128a9a68e8ae475e9f5f8303ff'::TEXT, ARRAY[1052]::BIGINT[]),
    (296::BIGINT, 'Se nota demasiado que sabe del curso. A veces es un poco ambigua a la hora de calificar los proyectos, y carga demasiado el curso comparado a otros profes. ASISTENCIA OBLIGATORIA; no justifica nada'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'La participación importa', 'Clases largas']::TEXT[], '2018-11-29T00:00:00+00:00'::TIMESTAMPTZ, '3bdd0f47c9b078f23b44b73496d819b763401828dd004f338c1282cfd545563f'::TEXT, ARRAY[1052]::BIGINT[]),
    (296::BIGINT, 'Adópteme maestra.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Deja trabajos largos', 'Tomaría su clase nuevamente']::TEXT[], '2018-11-23T00:00:00+00:00'::TIMESTAMPTZ, '7adefa922e7536d0258927058d671fd0749ce0021455ed03a3ccee6581ea7d1a'::TEXT, ARRAY[1037]::BIGINT[]),
    (296::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria']::TEXT[], '2018-02-07T00:00:00+00:00'::TIMESTAMPTZ, '4dfb2a76af88f1a81a21b80bfb81b0c20a42a2cfab695497ceb6e00d3bd03530'::TEXT, ARRAY[1037]::BIGINT[]),
    (296::BIGINT, 'Se nota que sabe mucho sobre la administración de proyectos y además logra transmitirlo. Es un poco despistada pero nada grave.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Da crédito extra', 'Exámenes retadores']::TEXT[], '2017-12-05T00:00:00+00:00'::TIMESTAMPTZ, '28475973bfe06dcf8d8982a154126dce61b4f988e6b040ea1701cf9bde9d6bf4'::TEXT, ARRAY[1052]::BIGINT[]),
    (296::BIGINT, 'Todo el trabajo lo hacen los asistentes, ni siquiera redacta sus propios documentos y el material lo toma de otros profesores, no programa nada y es un profesor muy obsoleto.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2017-11-27T00:00:00+00:00'::TIMESTAMPTZ, '0bfb1177f966bfaff8a9a23fd36b22b452fe4b0baacb3dce21d69ae11289cb2b'::TEXT, ARRAY[1037]::BIGINT[]),
    (296::BIGINT, 'Es un profesor que sabe el mínimo, se nota demasiado que no programa y su contenido lo toma de otros profesores.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2017-10-09T00:00:00+00:00'::TIMESTAMPTZ, 'd7bd3685b7f334960c6598e39e2d44699bc7f66505287ec815148e77932446ad'::TEXT, ARRAY[1029]::BIGINT[]),
    (296::BIGINT, 'Da la materia desordenada. Hace tests de personalidad que no aportan nada, solo perder tiempo de clases. Evalúa hasta lo que no explica bien. Deja lecturas. Exámenes un poco complicados. Se ve que sabe pero le cuesta externarlo.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Exámenes retadores']::TEXT[], '2017-06-23T00:00:00+00:00'::TIMESTAMPTZ, 'dd8c6d274e5e754715914908d997acabf65688847302bbb95c2beac0bca724a5'::TEXT, ARRAY[1052]::BIGINT[]),
    (296::BIGINT, 'Profesora dedicada, si usted le pregunta ella responde, le gusta que participen en clase. A veces se enreda con algunas cosas. Califica fuerte y los examenes no son sencillos, pero si estudia pasa. Los proyectos son bastante pesados y le encantan las interfaces. Siempre pasa lista.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-14T00:00:00+00:00'::TIMESTAMPTZ, '366e76f60f79037893cb42f79dc84e5108dadd398cced29593c34a488c57a4e8'::TEXT, ARRAY[1029]::BIGINT[]),
    (296::BIGINT, 'Fue muy desordenada dando la materia. se perdió mucho tiempo con actividades que no aportaban al curso y luego no le alcanzaba el tiempo para ver la materia pero de igual manera nos la evaluaba en tareas y proyectos. Hay que estarle preguntando personalmente fuera de clases para que ayude a corregir'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Asistencia obligatoria']::TEXT[], '2017-06-13T00:00:00+00:00'::TIMESTAMPTZ, '5f6eca658394f76d08722c555fae3edde7879dd0e33b3e447696b92a9f16a9ac'::TEXT, ARRAY[1052]::BIGINT[]),
    (296::BIGINT, 'Parecia que tenia poco interes en dar la clase, devolvia los examenes muy despues y los examenes tenian errores que eventualmente no corrigio.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Da crédito extra', 'Muchos proyectos grupales']::TEXT[], '2016-12-05T00:00:00+00:00'::TIMESTAMPTZ, '029b9f56fd39a69b1c70aa14bdff2589a345277986dab6b50c304c5656f530eb'::TEXT, ARRAY[1029]::BIGINT[]),
    (296::BIGINT, 'Muy mala profesora para este curso. No explica, brinda PDFs con instrucciones tomadas de internet para "aprender" cosas de Android pero no las explica. Hay que tener mucho autoaprendizaje. Deja proyectos y examenes complicados a pesar de no explicar nada. Se le pide ayuda y no sabe la respuesta.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2016-12-05T00:00:00+00:00'::TIMESTAMPTZ, '8f4221209368b7c81d4a89e6771e4c6be1f07b53c988feb554cc33b9321a6ef2'::TEXT, ARRAY[1137]::BIGINT[]),
    (296::BIGINT, 'Esta profe sabe mucho, pero de cuestiones de modelos y diagramas. Debería mejor dar requerimientos o algún otro curso que no sea de programar, porque se nota que casi no sabe de ello. Casi que obliga a programar web pero no enseña nada al respecto.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Deja trabajos largos']::TEXT[], '2016-11-04T00:00:00+00:00'::TIMESTAMPTZ, '889d1ed6f7ffa2f26a81d6f96f92530d46fd7c3ee46a56cb1480cd4c6f580b1f'::TEXT, ARRAY[1037]::BIGINT[]),
    (296::BIGINT, 'Muy buena profesora, sabe lo que hace y siempre trata de ser lo más organizada posible. Enseña con claridad si se le pone interés y se preocupa por el estudiante. Es exigente con algunas cosas pero si se trabaja ayuda mucho. Totalmente recomendada.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Pocos exámenes', 'Tomaría su clase nuevamente']::TEXT[], '2016-07-18T00:00:00+00:00'::TIMESTAMPTZ, '3cd6b35f8e860e5d7395389cc88c0030e02ac49e1c0876e004f5fd81ee484c76'::TEXT, ARRAY[1137]::BIGINT[]),
    (296::BIGINT, 'Profesora que podria mejorar sus clases, en algunas clases se nota que no domina algunos temas , da oportunidad de ganar algunos puntos extras, le encanta las interfaces gráficas . Haciendo todas las tareas uno sale con buena nota .'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Da crédito extra']::TEXT[], '2016-07-06T00:00:00+00:00'::TIMESTAMPTZ, 'b0e05902ba06f4a35bf2b663f9297ebd3a6efb748772ab22c3224cf8d9ec422e'::TEXT, ARRAY[1037]::BIGINT[]),
    (296::BIGINT, 'Ella es muy organizada, hay que hacer laboratorios sencillos todas las clases. Los exámenes no son fáciles y los proyectos son LARGOS y más orientados a programación web que a bases de datos. Sabe de bases de datos pero se queda corto su conocimiento. En resumen, van a aprender a programar web.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2016-06-28T00:00:00+00:00'::TIMESTAMPTZ, '384d03721d4bcb477da0c936e57a4f56413b9cfd498539efc57d11afb418710f'::TEXT, ARRAY[1037]::BIGINT[]),
    (296::BIGINT, 'Si uno le pone la materia no es tan difícil. Los exámenes si lo ponen a pensar y demostrar que usted domina la materia. Usa presentaciones para las clases.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Exámenes retadores']::TEXT[], '2016-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'f42f404f40b8b5da618005d4ae7adc5e784325b00e77ef69cc46904ef395795d'::TEXT, ARRAY[1029]::BIGINT[]),
    (296::BIGINT, 'Buena profesora, con muchas ganas de que los estudiantes aprendan. Tiene que mejorar algunas cosas y dominar un poco más la materia en algunos temas. Deja progras en las que se aprende bastante, brinda opciones para ganar puntos extra, dispuesta a ayudar y explicar las veces que sean necesarias.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2016-06-24T00:00:00+00:00'::TIMESTAMPTZ, '5474a6bfe453786b0e1c906d606ec41096340143f1c161d9bcfa6fa148e9fbd7'::TEXT, ARRAY[1037]::BIGINT[]),
    (296::BIGINT, 'La asistencia, hacer cada tarea y laboratorio es crucial para sacar buena nota,los examenes son un poco confusos no sabe redactarlos de una forma clara, recomendaria que mandara lecturas porque aveces ensena las cosas muy superficialmente,rubrica de proyectos muy mal redactadas con falta de detalle.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria']::TEXT[], '2016-06-21T00:00:00+00:00'::TIMESTAMPTZ, '7bf23b95c968a1740c99c62d1597cd4f60ff28e6cbd978565bb9fc2fcf95f3d0'::TEXT, ARRAY[1029]::BIGINT[]),
    (296::BIGINT, 'Puede mejorar! Pero preferiría matricular con otro profesor!! Es buena persona.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-06T00:00:00+00:00'::TIMESTAMPTZ, '302ba2d5ba550f3821eacb8e8af6100665e37cd16ce8b995fd73685d3ead7139'::TEXT, ARRAY[1056]::BIGINT[]),
    (296::BIGINT, 'Considero que este es el aspecto que le falta, las especificaciones del proyecto no son muy claras y puede que ella tampoco entienda que es lo que trata. Ayuda mucho si, pero puede que hasta lo enrede mas a uno!'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Exámenes retadores']::TEXT[], '2016-05-28T00:00:00+00:00'::TIMESTAMPTZ, '54d79444126b3c44ce02b5c9d0d14d1ac02fc1a15966bf05ec0c0f81377494b9'::TEXT, ARRAY[2917]::BIGINT[]),
    (296::BIGINT, 'Es muy respetuosa y seria(eso es bueno), las clases a veces aburren, no ayuda aún si te esforzaste al 1000% y progras largas que solo te quitan tiempo por tener que repetir código, espero mejore por el bien del TEC y ella, la estimo y escribo esto con la esperanza que lo lea y comprenda.'::TEXT, 6.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-12-24T00:00:00+00:00'::TIMESTAMPTZ, '57ab05f093da402664e63c0ef6332316a7b9cfa1eac4ece67749201c761130b8'::TEXT, ARRAY[1030]::BIGINT[]),
    (296::BIGINT, 'Excelente profesora, sabe explicar a los estudiantes y ofrece toda su ayuda para los proyectos. En cuanto a estos, son bastante largos pero trata de que sean entretenidos y se aprende muchísimo. JAMÁS entregue algún trabajo con faltas de ortografía. La recomiendo al 100%'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-30T00:00:00+00:00'::TIMESTAMPTZ, '532eeff8071fa95d375d2dd3380a632a58d41419bfee43d7cc3c843670d880c4'::TEXT, ARRAY[1037]::BIGINT[]),
    (296::BIGINT, 'La profe es buena, y se le entiende muy bien lo poco que explica, porque en general el curso fue exposiciones de los mismos estudiantes todas las clases. Un poco exigente con las tareas y proyectos.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-28T00:00:00+00:00'::TIMESTAMPTZ, 'c157edb3973e5ccba652f3973f34d8cecbe9c62aaddf07619f5ce3bf268ad28c'::TEXT, ARRAY[1056]::BIGINT[]),
    (296::BIGINT, 'Es muy buena profesora, se entiende la gran mayoría y si no atiende cualquier duda. Si es exigente con los trabajos y la documentación, por lo que se debe ser ordenado. Si la profe nota que un grupo nunca falta y le pone empeño lo ayuda mucho al final, pero sólo si se lo merece. ¡RECOMENDADÍSIMA!'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-27T00:00:00+00:00'::TIMESTAMPTZ, 'df2cdf3718e52677bb3a1651d15e600250e8e50fbe2ed1b9929ea1b039660daa'::TEXT, ARRAY[1037]::BIGINT[]),
    (296::BIGINT, 'Muy buena profe, explica bastante claro y se preocupa por el aprendizaje del estudiante. Las progras son largas pero se aprende mucho. Muy recomendada.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-19T00:00:00+00:00'::TIMESTAMPTZ, 'f8b3d7e5c0abde4c07adceda5ec41568f02640c11da8802f7ca94631e7bb3d81'::TEXT, ARRAY[1037]::BIGINT[]),
    (296::BIGINT, 'Excelente profesora, de las mejores que he tenido en el TEC, explica bien, atiende dudas, proyectos super útiles y entretenidos. Le gusta que le lleven progras con buena interfaz y sí le gusta mucho da puntos extra, pero sino le gusta solamente dice que muy simple, pero no quita puntos ni nada.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-10-28T00:00:00+00:00'::TIMESTAMPTZ, 'db48aa409806d500c76141f9430dab80e748d832294de40d2f11ae686be62518'::TEXT, ARRAY[1037]::BIGINT[]),
    (296::BIGINT, 'En clases lo que hace es leer presentaciones, en lugar de explicar temas lo pone a uno exponerlos y uno no aprende, todo lo ve por encima, los labs solo sirven para perder tiempo, en las revisiones califica mas la interfaz y ortografía, las progras son largas y aburridas, no enfoca el curso bien.'::TEXT, 8.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('45','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-10-09T00:00:00+00:00'::TIMESTAMPTZ, '4919583b3c7dfe8086faaf252d0afcd1eee9d4e28011900f2200d5d8df5e8c13'::TEXT, ARRAY[1030]::BIGINT[]),
    (296::BIGINT, 'le interesa que los estudiantes aprendan; se aprende mucho haciendo los proyectos; proyectos pueden ser MUY largos; puede ser generosa en las revisiones; no se aprende mucho en clase; en los examenes no espere ganar mas de 75 pero es facil sacarse mas de 60; tareas faciles (hagalas todas);'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-30T00:00:00+00:00'::TIMESTAMPTZ, 'e60643567216eb79199f8b2c7414758f50766cca387ab804a60620f4630a2e1c'::TEXT, ARRAY[1037]::BIGINT[]),
    (296::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-13T00:00:00+00:00'::TIMESTAMPTZ, '65405193c9eb32673e76270898b36ee32bf490eea0c9fc3f491d948d7ffa9107'::TEXT, ARRAY[1030]::BIGINT[]),
    (296::BIGINT, 'De los peores profes con los q he matriculado, no enseña nada útil, le da mas valora la documentacion'::TEXT, 8.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('20','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-02T00:00:00+00:00'::TIMESTAMPTZ, 'd7c85b268b0dfdf4b27ded2425ede13c9252710e186d08a979b05d3144f7898a'::TEXT, ARRAY[2917]::BIGINT[]),
    (296::BIGINT, 'Se realiza mucho laboratorio (con el que se aprende bastante). Las progras son largas y tienen que ser muy agradables visualmente (como debería ser siempre). Es flexible con entregas y los mismos proyectos. Los examenes valen mucho, y por eso se puede ''casi'' perder el curso fácil. Recomendada!'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-01T00:00:00+00:00'::TIMESTAMPTZ, '55f75b24be4762fc5a4384a98cece47cf4b0935164932dcd5af7806677781934'::TEXT, ARRAY[1037]::BIGINT[]),
    (296::BIGINT, 'Es una profesora muy organizada. Utiliza muchos labs para que uno aprenda haciendo, lo cual me parece bien, aunque sí es muy inflexible en la mayoría de los casos. Las progras que deja son muuuuy largas, pero se aprende bastante, además nunca tiene problema en atender dudas, la recomiendo.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-01T00:00:00+00:00'::TIMESTAMPTZ, '70ef7e5a0e34b69b304e17d1add1b6fd2c639d103b1396663719bd3b392fe0e5'::TEXT, ARRAY[1037]::BIGINT[]),
    (296::BIGINT, 'Tendrá que usar su tiempo para hacer presentaciones del agrado de la profe, maquetas que no son muy útiles. Enseña bien sobre cómo hacer las docus, pero de programación no es la gran cosa (al menos se practica con los labs)'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-03-28T00:00:00+00:00'::TIMESTAMPTZ, 'bee6b50a19a47a1f05115a735f881bf80e48a8c8baa4e8800b671f2f5667a690'::TEXT, ARRAY[1037]::BIGINT[]),
    (296::BIGINT, 'Pide mucho en la parte de documentación y la verdad no se aprende mucho, las clases son aburridas a puras presentaciones, los proyectos son fáciles pero largos.'::TEXT, 8.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-02-10T00:00:00+00:00'::TIMESTAMPTZ, '26da0f7801799b1d3011314ceb272c87c25ffa57b663582de8610cd70d7f087c'::TEXT, ARRAY[1030]::BIGINT[]),
    (296::BIGINT, 'Quienes dicen que esta profesora es buena o ruda es que no conocen a profes de verdad, como Torres, Nuñez, Helo o Eddy. No ve ni 1/10 parte de la materia que se ve con Nuñez. Y sus progras son cientos de veces más fáciles. Ella no da Bases de Datos, sino una Introducción super super básica.'::TEXT, 8.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-21T00:00:00+00:00'::TIMESTAMPTZ, '4ae7d282677286ffc7b029cf51e8498547c4ca477fa2da2cf54ada3ccd5648e9'::TEXT, ARRAY[1037]::BIGINT[]),
    (296::BIGINT, '¡PÉSIMA PROFESORA!. Clases increíblemente aburridas a punta de presentaciones de Word (no todas de ella, algunas las toma prestadas de otros profesores, y se le olvida cambiar el nombre). Exámenes fáciles, progras fáciles. Si desea llevar un curso fácil y pasable; lleve con ella.'::TEXT, 10.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-21T00:00:00+00:00'::TIMESTAMPTZ, 'ea1518fb8c5bccab5d5c936c9e4d3ded57f4676123e4ffb95d995851f497043b'::TEXT, ARRAY[1030]::BIGINT[]),
    (296::BIGINT, 'Excelente profe!'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-07T00:00:00+00:00'::TIMESTAMPTZ, '4a7043cba981e9031f483df27406d0e85d0f79efb1f5bbcc34baa2ceeaab3d64'::TEXT, ARRAY[1037]::BIGINT[]),
    (296::BIGINT, 'Exige mucho en la documentación, las progras no son difíciles, pero si largas y los exámenes imposibles, pero si es muy buena profe, explica lo necesario para uno arrancar después solo.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-12-01T00:00:00+00:00'::TIMESTAMPTZ, 'bcf6b2b08ba804304e7dec8687208245edb1510672c735f5820862962d3b3e2e'::TEXT, ARRAY[1030]::BIGINT[]),
    (296::BIGINT, 'Excelente profe!!!'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-22T00:00:00+00:00'::TIMESTAMPTZ, '951496298b9e765b5f83deed2444d3021270b1f1f9057e0ce4d5595185a8fc4d'::TEXT, ARRAY[1037]::BIGINT[]),
    (296::BIGINT, 'Una profe normal, a veces se enreda sola, da cursos en los que no sabe mucho del tema solo lo que copia de algún libro o de Internet exige mucho con la documentación. Esa profesora debería de dar cursos como Requerimientos, AP o Diseño que al parecer sabe del tema y no los curso que da actualmente.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('40','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-18T00:00:00+00:00'::TIMESTAMPTZ, 'a9d6385ae797068da6194890aff9eede4005261a5d48cfc146769fdd33815cd9'::TEXT, ARRAY[1037]::BIGINT[]),
    (296::BIGINT, 'Una buena profe sinceramente , jode mucho con las cosas de documentación y relacionado pero al final esas cosas hay que irlas aprendiendo.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-18T00:00:00+00:00'::TIMESTAMPTZ, '0765b644b71d0322b5b5c308643715fc834ef127495b5cf3f4881a4367b4e6ea'::TEXT, ARRAY[1037]::BIGINT[]),
    (296::BIGINT, 'Buena profe, explica biensillo. Las progras no las va a terminar al 100%, eso se lo aseguro. Da puntos extra y bueno, los exámenes son imposibles.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-18T00:00:00+00:00'::TIMESTAMPTZ, 'eb14ceec9e06bb41cc1607ebf96cec5a77b7eb36f5584e9f1b5353dbb7286882'::TEXT, ARRAY[1030]::BIGINT[]),
    (296::BIGINT, 'Muy exigente en cuanto las progras y tareas pero se aprende mucho con ella'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-17T00:00:00+00:00'::TIMESTAMPTZ, 'fcf3fd48b8ab826fa6429f557513a819cf716314a075cd8cb2b003b246e34932'::TEXT, ARRAY[1030]::BIGINT[]),
    (296::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-17T00:00:00+00:00'::TIMESTAMPTZ, '5e97a623aee5a2ca1736e91ebd8af2a7a8fb2e49264edc8cce33038fb438bceb'::TEXT, ARRAY[1037]::BIGINT[]),
    (296::BIGINT, 'La profe se preocupa porque usted ENTIENDA la materia, le gusta ayudar en todo lo que pueda y la verdad se aprende mucho! Si es exigente, pero no lo deben ser los profesores del TEC? La verdad lo exigente no debería importar si usted APRENDE. Y con ella es así.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, '163d3d2bb8cafe974a87d553dfb7ea67fd982ef468df8a4cc23adbe7ee361907'::TEXT, ARRAY[1037]::BIGINT[]),
    (296::BIGINT, 'Profe que pide mucho, pero no es muy buena explicando en comparación con lo que exige.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, 'c3144ef867a11560c7798c14f8bb176fcc1012dd612ea40e93dfc5ad6ba42fba'::TEXT, ARRAY[1030]::BIGINT[]),
    (296::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, 'f8e9c83a3354cc5a07e50589c1fa882317f5d839adddf4f27408dbc7778a4705'::TEXT, ARRAY[1037]::BIGINT[]),
    (296::BIGINT, 'La profe siempre está dispuesta a ayudar. Es muy dinámica y explica lo suficiente hasta que nos quede clara la materia. Es socada, pero el tema de las progras siempre es muy emocionante.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, '87c1c164be9a91530b4967ed7e65ba50b32beb4c428913aca24c20369fd830da'::TEXT, ARRAY[1030]::BIGINT[]),
    (296::BIGINT, 'Es de esos profesores que "jode" mucho, pero no se aprende la gran cosa'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('45','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, 'ce170759d41743ef179cc9fcc3c3c3ec0be939065ca857642f608c28a6f8d42c'::TEXT, ARRAY[1030]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
